/* @autogenerated */
import { matchColumns, normalizeHeader, similarity } from './column-match';

describe('column-match', () => {
  it('normalizes accents, case, separators and camelCase', () => {
    expect(normalizeHeader('Correo  Electrónico')).toBe('correo electronico');
    expect(normalizeHeader('welcomeAt')).toBe('welcome at');
    expect(normalizeHeader('blocked-until')).toBe('blocked until');
  });

  it('scores equal headers as 1 and unrelated ones low', () => {
    expect(similarity('NOMBRE', 'Nombre')).toBe(1);
    expect(similarity('emailverified', 'email verified')).toBe(0.95);
    expect(similarity('correo', 'correo electrónico')).toBeGreaterThanOrEqual(0.75);
    expect(similarity('teléfono', 'contraseña')).toBeLessThan(0.6);
  });

  it('assigns each header to the most similar field only once', () => {
    const headers = ['Nombre', 'Correo electronico', 'Contraseña', 'Notas'];
    const result = matchColumns(headers, [
      { field: 'name', names: ['Nombre', 'name'] },
      { field: 'email', names: ['correo electrónico', 'email'] },
      { field: 'password', names: ['contraseña', 'password'] },
      { field: 'federatedProvider', names: ['proveedor federado', 'federatedProvider'] },
    ]);

    expect(result).toEqual({ name: 0, email: 1, password: 2, federatedProvider: null });
  });

  it('does not reuse a header already taken by a better match', () => {
    const result = matchColumns(
      ['email'],
      [
        { field: 'email', names: ['email'] },
        { field: 'emailVerified', names: ['email verified'] },
      ],
    );

    expect(result).toEqual({ email: 0, emailVerified: null });
  });
});
